#include "mspa/runtime/agent_store.hpp"
namespace mspa {Result<void>AgentStore::insert(AgentPsychState s){if(!s.id.valid())return make_error(ErrorCode::InvalidArgument,"invalid agent id");if(agents_.count(s.id))return make_error(ErrorCode::DuplicateAgent,"agent already exists");agents_.emplace(s.id,std::move(s));return {};}Result<void>AgentStore::erase(AgentId id){if(!agents_.erase(id))return make_error(ErrorCode::UnknownAgent,"agent not found");return {};}bool AgentStore::contains(AgentId id)const noexcept{return agents_.count(id)!=0;}AgentPsychState*AgentStore::find(AgentId id)noexcept{auto it=agents_.find(id);return it==agents_.end()?nullptr:&it->second;}const AgentPsychState*AgentStore::find(AgentId id)const noexcept{auto it=agents_.find(id);return it==agents_.end()?nullptr:&it->second;}std::size_t AgentStore::size()const noexcept{return agents_.size();}const std::map<AgentId,AgentPsychState>&AgentStore::all()const noexcept{return agents_;}}
